from pathlib import Path

# Vista técnico
p=Path('ip-servicio-v2.js')
s=p.read_text(encoding='utf-8')
start=s.index("  function manualBox()")
end=s.index("  const DELETE_IDS=new Set();")
new_block=r'''  function limpiarPlan(v){return up(String(v||'').replace(/\/[0-9]+$/,''))}
  function planCandidato(c){const plan=limpiarPlan(c.plan_detectado||c.queue_parent||'');return plan?`<div class="muted" style="margin-top:7px"><b>PLAN / GRUPO SIMPLE QUEUES:</b> ${esc(plan)}</div>`:'<div class="muted" style="margin-top:7px">PLAN: pendiente de lectura desde Simple Queues</div>'}
  function candidatoTecnico(c){const cliente=up(O?.cliente_nombre||'CLIENTE'),queue=up(c.queue_name||c.comentario||'SIN NOMBRE');return `<div class="candidate"><span class="badge wait">⚠️ IP TENTATIVA</span><div class="ip">${esc(c.address)}</div><div style="margin-top:8px"><div class="label">CLIENTE DE LA OT</div><div class="value">${esc(cliente)}</div></div><div style="margin-top:8px"><div class="label">QUEUE / NOMBRE MIKROTIK</div><div class="value">${esc(queue)}</div></div>${planCandidato(c)}<div class="muted" style="margin-top:8px"><b>CONFIANZA:</b> ${esc(c.score??'—')} · ${(c.razones||[]).map(x=>esc(x)).join(' · ')}</div><div class="msg warn" style="margin-top:10px">Esta IP todavía NO es definitiva. Espera la confirmación del responsable de IP.</div></div>`}
  window.estadoIp=async function(){try{mostrarCorreoDatos();const d=await post(API_IP,'status',{orden_id:ordenId()}),q=d.solicitud,cs=d.candidatos||[];if(d.orden){O.plan_final=d.orden.plan_final??O.plan_final;O.tv_final=d.orden.tv_final??O.tv_final;sessionStorage.setItem(INSTKEY,JSON.stringify(O))}$('candidatos').innerHTML='';if(!q){$('ipEstado').innerHTML=`<span class="badge">IP AÚN NO SOLICITADA</span><div class="row" style="margin-top:10px"><div class="item"><div class="label">Cliente</div><div class="value">${esc(up(O?.cliente_nombre||'—'))}</div></div><div class="item"><div class="label">Plan real</div><div class="value">SE LEERÁ DEL ROUTER</div></div></div><div class="muted" style="margin-top:8px">Cuando termines la parte física, solicita la IP. El buscador comparará los registros nuevos de MikroTik con el nombre del cliente y el queue.</div>`;$('solicitar').classList.remove('hidden');$('solicitar').textContent='📡 SOLICITAR IP';$('actualizar').classList.add('hidden');$('stIp').textContent='PENDIENTE';return}$('solicitar').classList.add('hidden');if(q.estado==='ASIGNADA'){$('actualizar').classList.add('hidden');const plan=limpiarPlan(O.plan_final||'POR VERIFICAR EN ROUTER');$('ipEstado').innerHTML=`<span class="badge okb">✅ IP CONFIRMADA</span><div class="ip">${esc(q.ip_asignada)}</div><div class="row" style="margin-top:10px"><div class="item"><div class="label">Cliente</div><div class="value">${esc(up(O?.cliente_nombre||'—'))}</div></div><div class="item"><div class="label">Plan / grupo Simple Queues</div><div class="value">${esc(plan)}</div></div></div>${q.observacion?`<div class="muted" style="margin-top:8px">${esc(q.observacion)}</div>`:''}`;$('stIp').textContent='✅ IP CONFIRMADA · '+q.ip_asignada;return}$('actualizar').classList.remove('hidden');$('actualizar').textContent='🔄 REVISAR IP';$('stIp').textContent=cs.length?'⚠️ IP TENTATIVA':'⏳ ESPERANDO IP';$('ipEstado').innerHTML=`<span class="badge wait">${cs.length?'⚠️ IP TENTATIVA DETECTADA':'⏳ BUSCANDO IP'}</span><div class="row" style="margin-top:10px"><div class="item"><div class="label">Cliente</div><div class="value">${esc(up(O?.cliente_nombre||'—'))}</div></div><div class="item"><div class="label">Solicitud</div><div class="value">${esc(fmtFecha(q.solicitado_at))}</div></div></div><div class="muted" style="margin-top:8px">Último escaneo: ${esc(fmtFecha(q.detector_ultimo_scan))}</div>`;if(!cs.length)$('candidatos').innerHTML='<div class="msg warn">Todavía no aparece una coincidencia suficientemente confiable en MikroTik.</div>';else $('candidatos').innerHTML=cs.map(candidatoTecnico).join('')}catch(e){show(e.message,'err')}};
  window.solicitarIp=async function(){try{await post(API_O,'request-ip',{orden_id:ordenId(),plan_final:'',tv_final:Boolean(O.tv_final??O.tv_solicitada)});show('✅ Solicitud de IP enviada. El buscador MikroTik ya está revisando candidatos.');await window.estadoIp()}catch(e){show(e.message,'err')}};
'''
s=s[:start]+new_block+s[end:]
p.write_text(s,encoding='utf-8')

# Vista responsable autorizado
p=Path('asignacion-ip.html')
s='''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Control de IP · DISPROTEL</title><style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;background:linear-gradient(135deg,#f7f9fb,#eaf3ff);color:#17313d;margin:0;padding:14px}.wrap{max-width:900px;margin:auto}.card{background:#fff;border-radius:18px;padding:20px;box-shadow:0 7px 24px rgba(0,0,0,.08);margin:14px 0}.muted{color:#60737c;font-size:13px}.req,.cand{border:1px solid #d7e1e5;border-radius:14px;padding:14px;margin-top:10px}.cand{background:#fbfdff}.badge{display:inline-block;padding:6px 9px;border-radius:999px;background:#fff3cd;color:#725b00;font-size:12px;font-weight:800}.ip{font-size:24px;font-weight:900;margin:7px 0}.label{font-size:12px;color:#60737c}.value{font-weight:800;margin-top:2px}input{width:100%;padding:12px;border:1px solid #cbd8de;border-radius:10px;font-size:16px}button{display:block;width:100%;border:0;border-radius:12px;padding:13px;background:#17313d;color:#fff;font-size:15px;font-weight:800;margin-top:10px}.secondary{background:#e8eef1;color:#17313d}.hidden{display:none!important}.msg{padding:12px;border-radius:10px;margin-top:12px}.ok{background:#e8f6ed;color:#1b6c43}.err{background:#fdecec;color:#9d2525}.row{display:grid;grid-template-columns:1fr 1fr;gap:10px}@media(max-width:620px){body{padding:8px}.card{padding:14px;margin:8px 0}.row{grid-template-columns:1fr}.ip{font-size:21px}}</style></head><body><div class="wrap"><section class="card" id="login"><h1>📡 Control de IP</h1><div class="muted">Revisión y confirmación de IP detectada por MikroTik.</div><input id="usuario" placeholder="Usuario" style="margin-top:10px"><input id="pin" inputmode="numeric" placeholder="PIN" style="margin-top:8px"><button id="entrar">ENTRAR</button><div id="loginMsg"></div></section><div id="app" class="hidden"><section class="card"><h2 id="quien"></h2><button id="recargar" class="secondary">🔄 ACTUALIZAR SOLICITUDES</button><button id="salir" class="secondary">CAMBIAR USUARIO</button></section><section class="card"><h2>🔔 Solicitudes de IP</h2><div id="lista"></div></section><div id="msg"></div></div></div><script>const API='https://ajnbswrwnjpjypjiorye.supabase.co/functions/v1/inventario-ip-candidatos',KEY='disprotel_ip_test';let US='',PIN='',timer=null;const $=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const up=v=>String(v??'').toLocaleUpperCase('es-EC');const plan=v=>up(String(v||'').replace(/\/[0-9]+$/,''));async function api(action,p={}){const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({usuario:US,pin:PIN,action,...p})});const d=await r.json().catch(()=>({error:'Respuesta inválida'}));if(!r.ok)throw new Error(d.error||'Error');return d}function show(t,c='ok'){$('msg').className='msg '+c;$('msg').textContent=t}function fmt(v){try{return new Date(v).toLocaleString('es-EC')}catch{return v||'—'}}async function cargar(){try{const d=await api('pending-review'),arr=d.solicitudes||[];$('lista').innerHTML=arr.map(s=>{const o=s.orden||{},cs=s.candidatos||[];return `<div class="req"><b>${esc(o.id_orden||'')} · ${esc(up(o.cliente_nombre||''))}</b><div class="muted">Solicitud: ${esc(fmt(s.solicitado_at))}</div>${cs.length?cs.map(c=>`<div class="cand"><span class="badge">⚠️ IP TENTATIVA</span><div class="ip">${esc(c.address)}</div><div class="row"><div><div class="label">CLIENTE OT</div><div class="value">${esc(up(o.cliente_nombre||'—'))}</div></div><div><div class="label">QUEUE MIKROTIK</div><div class="value">${esc(up(c.queue_name||c.comentario||'—'))}</div></div></div><div style="margin-top:8px"><div class="label">PLAN / GRUPO SIMPLE QUEUES</div><div class="value">${esc(plan(c.plan_detectado||c.queue_parent||'PENDIENTE'))}</div></div><div class="muted" style="margin-top:7px">Confianza: ${esc(c.score??'—')} · ${(c.razones||[]).map(esc).join(' · ')}</div><button onclick="confirmar('${o.id}','${c.id}')">✅ CONFIRMAR ESTA IP</button></div>`).join(''):'<div class="msg err">Todavía no hay candidata confiable.</div>'}<div class="cand"><b>✏️ CORREGIR / CONFIRMAR OTRA IP</b><input id="manual-${s.id}" inputmode="decimal" placeholder="Ej. 172.25.1.120"><input id="obs-${s.id}" placeholder="Observación opcional" style="margin-top:7px"><button onclick="manual('${s.id}','${o.id}')">✅ CONFIRMAR IP CORRECTA</button></div></div>`}).join('')||'<div class="muted">No hay solicitudes pendientes.</div>'}catch(e){show(e.message,'err')}}async function confirmar(orden,cand){if(!confirm('¿Confirmar esta IP como definitiva?'))return;try{await api('confirm',{orden_id:orden,candidato_id:cand});show('✅ IP confirmada. El técnico ya la verá como IP CONFIRMADA.');await cargar()}catch(e){show(e.message,'err')}}async function manual(sol,orden){const ip=$('manual-'+sol).value.trim(),obs=$('obs-'+sol).value.trim();if(!ip)return show('Ingresa la IP correcta.','err');if(!confirm('¿Confirmar '+ip+' como IP definitiva?'))return;try{await api('assign-manual',{orden_id:orden,solicitud_id:sol,ip,observacion:obs});show('✅ IP corregida y confirmada.');await cargar()}catch(e){show(e.message,'err')}}async function entrar(){US=$('usuario').value.trim();PIN=$('pin').value.trim();try{const d=await api('pending-review');sessionStorage.setItem(KEY,JSON.stringify({usuario:US,pin:PIN}));$('login').classList.add('hidden');$('app').classList.remove('hidden');$('quien').textContent='Control IP · '+(d.me?.nombre||US);await cargar();timer=setInterval(cargar,8000)}catch(e){$('loginMsg').className='msg err';$('loginMsg').textContent=e.message}}$('entrar').onclick=entrar;$('recargar').onclick=cargar;$('salir').onclick=()=>{sessionStorage.removeItem(KEY);location.reload()};(async()=>{try{const s=JSON.parse(sessionStorage.getItem(KEY)||'null');if(s?.usuario&&s?.pin){$('usuario').value=s.usuario;$('pin').value=s.pin;await entrar()}}catch{sessionStorage.removeItem(KEY)}})();</script></body></html>'''
p.write_text(s,encoding='utf-8')

